interface FormData {
  platforms: Platform['key'][];
  billingCycle: string;
  currentStep: 1 | 2;
}

const getPlatformType = (planName: string):string => {
    return planName.toLowerCase().includes("web") ? "web" : "mobile";
};


const SelfServePlansPopup = ({
  planData,
  isLoading,
  setTriggerFreePlanPopup,
}: {
  planData: Plan[];
  isLoading: boolean;
  setTriggerFreePlanPopup: (val: boolean) => void;
}) => {
  // eslint-disable-next-line no-undef
  const intervalIdRef = useRef<NodeJS.Timeout | null>(null);

  const queryClient = useQueryClient();

  const {
    control,
    handleSubmit,
    watch,
    setValue,
    formState: { errors },
  } = useForm<FormData>({
    defaultValues: {
      platforms: [],
      billingCycle: 'annual',
      currentStep: 1,
    },
  });

  const [cbInstance, setCbInstance] = useState<ChargebeeInstance | null>(null);

  const watchedPlatforms = watch('platforms');
  const watchedBillingCycle = watch('billingCycle');
  const watchedCurrentStep = watch('currentStep');

  const { currentOrgReducer: currentOrg } = useSelector(
    (state: IReduxState) => state
  );

  const dispatch = useDispatch();

  const { planType, orgId } = currentOrg;

  const chargebeeCheckoutURl = `subscription/checkoutv2/organization/${orgId}`;

  const [recommendedPlan, setRecommendedPlan] = useState<string>('');
  const [isUpgrading, setIsUpgrading] = useState(false);

  const queryKey = useMemo(() => `currentSubscription${orgId}`, [orgId]);
  const paymentInfoKey = useMemo(() => `payment_info_${orgId}`, [orgId]);

  const { data: currentSubscription } = useFetchCurrentSubscription({
    queryKey,
    orgId,
  });

  const currentPlan = useMemo(
    () => currentSubscription?.yourPlan?.planType === 'paid',
    [currentSubscription?.yourPlan?.planType]
  );

  const restrictionContext = useRestrictionContext();
  const {
    setShowPricingModal
  } = restrictionContext as any;

  const renderPrice = useCallback((price: number) => {
    if (price % 1 === 0) {
      return price;
    }
    return price.toFixed(2);
  }, []);


  const priceCalc = useMemo(() => {
    if (planData && planData.length > 0 && watchedPlatforms.length > 0) {
      const selectedPlatform = watchedPlatforms[0];
      const perPlanData = planData.find(plan => {
        // eslint-disable-next-line no-underscore-dangle
        return getPlatformType(plan.name) === selectedPlatform;
      });

      if (perPlanData) {
        const { base_price, surcharge } = perPlanData;
        const annualSubscription = base_price * 12;
        const monthlySubscription =
          base_price * (surcharge.monthly / 100 + 1) * 12;

        const savings = monthlySubscription - annualSubscription;
        return {
          monthly: {
            price: renderPrice(
              base_price * (surcharge.monthly / 100 + 1)
            ).toString(),
            savings: '',
          },
          annual: {
            price: renderPrice(base_price).toString(),
            savings: renderPrice((savings/(12 * base_price) * 100 )).toString(),
          },
        };
      }
    }
    return {
      monthly: {
        price: '0',
        savings: '0',
      },
      annual: {
        price: '0',
        savings: '0',
      },
    };
  }, [planData, renderPrice, watchedPlatforms]);


  useEffect(() => {

    // eslint-disable-next-line no-undef
    let timeoutId: NodeJS.Timeout | null = null;

    const initializeChargebee = () => {
      if (window.Chargebee) {
        window.Chargebee.init({
          site: chargebeeSiteName || '',
        });
        setCbInstance(window.Chargebee.getInstance());
      } else {
        timeoutId = setTimeout(initializeChargebee, 100);
      }
    };

    initializeChargebee();
    return () => {
        if (timeoutId) {
            clearTimeout(timeoutId);
        }
    };
  }, []);

  const parsedPlan = useMemo(() => {
    if (!planData || planData.length === 0) {
      return [];
    }

    return planData.map(plan => {
      const {
        _id: id,
        limits,
        name, 
        recommended,
      } = plan;

      const { session } = limits;

      if (recommended) {
        setRecommendedPlan(name);
      }

      return {
        id,
        name,
        sessionCount: session,
        platform: getPlatformType(name)
      };
    });
  }, [planData]);

  useEffect(() => {
    if (currentPlan) {
      if (intervalIdRef.current) {
        clearInterval(intervalIdRef.current);
        intervalIdRef.current = null;
      }
      dispatch(getActiveSubscription(orgId));
      setIsUpgrading(false);
      message.success('Plan upgrade successful');
    }

    return () => {
      if (intervalIdRef.current) {
        clearInterval(intervalIdRef.current);
        intervalIdRef.current = null;
      }
      dispatch(getAppDropdown());
      setIsUpgrading(false);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentPlan, dispatch, orgId, setIsUpgrading]);

  const handleRefetchSubscription = useCallback(() => {
    intervalIdRef.current = setInterval(() => {
      queryClient.invalidateQueries(queryKey);
      queryClient.invalidateQueries(paymentInfoKey);
    }, 800);
  }, [queryClient, queryKey, paymentInfoKey]);

  const onFinish = useCallback(() => {
    const selectedPlatform = watchedPlatforms[0]; // For single platform selection
    const selectedPlan = parsedPlan.find(plan => plan.platform === selectedPlatform);
    if (!selectedPlan) {
        rollbar.error(
            `SELF SERVE PLAN - Selected plan not found for platform: ${selectedPlatform}`
        );
      return;
    }

    dispatch(
      trackPageViews(null, {
        eventName: 'wa_continue_with_starter_plan_clicked',
        track_type: 'event',
        eventProperty: {
          'chosen plan': selectedPlan.name,
          'recommended plan': recommendedPlan,
          'chosen platform': selectedPlatform === 'mobile' ? 'Mobile' : 'Web',
        },
      })
    );

    cbInstance?.openCheckout({
      hostedPage: () =>
        updateChargebeeLink(chargebeeCheckoutURl, {
          plan: selectedPlan.id,
          billing_frequency: watchedBillingCycle === 'monthly' ? 1 : 12,
        }),
      success(hostedPageId: string) {
        if (hostedPageId) {
          handleRefetchSubscription();
          cbInstance.closeAll();
          setShowPricingModal(false);
          setIsUpgrading(true);
        }
      },
    });
  }, [
    dispatch,
    parsedPlan,
    recommendedPlan,
    cbInstance,
    chargebeeCheckoutURl,
    watchedBillingCycle,
    watchedPlatforms,
    handleRefetchSubscription,
    setShowPricingModal,
  ]);

  const triggerFreePlanPopup = useCallback(() => {
    setTriggerFreePlanPopup(true);
    dispatch(
      trackPageViews(null, {
        eventName: 'wa_downgrade_to_free_plan_clicked',
        track_type: 'event',
      })
    );
  }, [dispatch, setTriggerFreePlanPopup]);

  const validateStep1 = useCallback(() => {
    const platforms = watchedPlatforms || [];
    return platforms.length > 0;
  }, [watchedPlatforms]);

  const validateStep2 = useCallback(() => {
    return !!watchedBillingCycle;
  }, [watchedBillingCycle]);

  const handleNextStep = useCallback(() => {
    if (validateStep1()) {
        if(watchedPlatforms.length === 2) {
             dispatch(
                trackPageViews(null, {
                    eventName: 'wa_talk_to_sales_for_both_platform_clicked',
                    track_type: 'event',
                })
            );
        }else{
            dispatch(
                trackPageViews(null, {
                    eventName: 'wa_see_feature_pricing_clicked',
                    track_type: 'event',
                    eventProperty: {
                        'chosen platform':
                        watchedPlatforms[0] === 'mobile' ? 'Mobile' : 'Web',
                    },
                })
            );
        }
      setValue('currentStep', 2);
    } else {
      message.error('Please select at least one platform to continue.');
    }
  }, [validateStep1, setValue, watchedPlatforms, dispatch]);

  const handleGoBack = useCallback(() => {
    setValue('currentStep', 1);
    setValue('platforms', []);
    setValue('billingCycle', 'annual');
  }, [setValue]);

  const handleFinish = useCallback(() => {
    if (validateStep2()) {
      onFinish();
    } else {
      message.error('Please select a billing cycle to continue.');
    }
  }, [validateStep2, onFinish]);

  const handlePlatformToggle = useCallback(
    (platformKey: Platform['key']) => {
      const currentPlatforms = watchedPlatforms || [];
      const newPlatforms = currentPlatforms.includes(platformKey)
        ? currentPlatforms.filter((key: string) => key !== platformKey)
        : [...currentPlatforms, platformKey];
      setValue('platforms', newPlatforms);
    },
    [watchedPlatforms, setValue]
  );

  const isPlatformSelected = useCallback(
    (platformKey: Platform['key']) => {
      return (watchedPlatforms || []).includes(platformKey);
    },
    [watchedPlatforms]
  );

  const handleBillingCycleSelect = useCallback(
    (billingKey: string) => {
      setValue('billingCycle', billingKey);
    },
    [setValue]
  );

  const isBillingCycleSelected = useCallback(
    (billingKey: string) => {
      return watchedBillingCycle === billingKey;
    },
    [watchedBillingCycle]
  );

  if (isUpgrading)
    return <UpgradeModal showModal={isUpgrading} isDowngrade={false} />;

  if (parsedPlan && parsedPlan.length > 0) {
    const getSessionCount = () => {
      if (watchedPlatforms.length > 0) {
        const selectedPlan = parsedPlan.find(plan => plan.platform === watchedPlatforms[0]);
        return selectedPlan?.sessionCount || 10000;
      }
      return parsedPlan[0]?.sessionCount || 10000;
    };

    return (
      <PlansModalLayoutV2
        isLoading={isLoading}
      >
        {isLoading ? (
            <ReactLoader />
        ) : (
          <>
            {watchedCurrentStep === 1 && (
              <Phases.Step1
                isPlatformSelected={isPlatformSelected}
                handlePlatformToggle={handlePlatformToggle}
                onNextStep={handleNextStep}
                onDowngrade={triggerFreePlanPopup}
                planType={planType}
                sessionCount={getSessionCount()}
                selectedPlatforms={watchedPlatforms}
              />
            )}
            {/* // * single platform upgrade */}
            {watchedCurrentStep === 2 && watchedPlatforms.length < 2 && (
              <Phases.Step2
                isBillingCycleSelected={isBillingCycleSelected}
                handleBillingCycleSelect={handleBillingCycleSelect}
                prices={priceCalc}
                onFinish={handleFinish}
                onGoBack={handleGoBack}
                platform={watchedPlatforms[0]}
                sessionCount={getSessionCount()}
              />
            )}
            {/* // * multi platform upgrade */}
            {watchedCurrentStep === 2 && watchedPlatforms.length === 2 && (
              <Phases.Step2MultiPlatform
                onGoBack={handleGoBack}
                onCloseModal={() => 
                {
                    setShowPricingModal(false);
                    // * reset steps
                    setValue('currentStep', 1);
                    setValue('platforms', []);
                }}
              />
            )}
          </>
        )}
      </PlansModalLayoutV2>
    );
  }

  return null;
};

export default memo(SelfServePlansPopup);
