import React, { memo, useCallback, useEffect, useMemo, useState } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { useQueryClient } from 'react-query'

import { getActiveSubscription } from 'redux/actions/subscription'
import { getAppDropdown } from 'redux/actions/appdropdown'
import { trackPageViews } from 'redux/actions/trackingReport'

import { Button, Modal, message } from 'antd'

import SettingApi from 'services/settingApi'

import { freePlanFeatures } from 'Utils/constants'

import { rollbar } from 'components/common/rollbar'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'

import { useFetchCurrentSubscription } from 'components/features/setting/useSettingPage'
import { TitleMessage, Description, ButtonsWrapper, ListWrapper, SubTitle, FeatureList, DisabledList } from './styles'


let intervalId;

const FreePlanModal = ({setTriggerFreePlan, triggerFreePlanPopup}) => {

  const queryClient = useQueryClient();
  const dispatch = useDispatch()

  const {
    currentOrgReducer: currentOrg
  } = useSelector(state => state)

  const { orgId } = currentOrg

  const [downgradeSuccess, setDowngradeSuccess] = useState(false)
  const [downgrading, setDowngrading] = useState(false)
  const { setShowPricingModal } = useRestrictionContext()

  const queryKey = useMemo(() => `currentSubscription${orgId}`, [orgId])

  const { data: currentSubscription } = useFetchCurrentSubscription({
    queryKey,
    orgId
  })

  const currentPlan = useMemo(
    () => currentSubscription?.yourPlan?.planType === 'free',
    [currentSubscription?.yourPlan?.planType]
  );

  const handleRefetchSubscription = () => {
    intervalId = setInterval(() => {
      queryClient.invalidateQueries(queryKey);
    }, 800);
  };
  
  
  const downgradeToFree = async () => {
      try{
        setDowngrading(true)
        const res = await SettingApi.downgradeToFreePlan(orgId);
        if(res.status === 200){
            handleRefetchSubscription()
        }
    } catch(error) {
        rollbar.error('Free Plan Downgrade Error:', error)
        message.error( error.response.data['error']['message'] || 'Something went wrong. Please try again later.')
    }
  }
  
  useEffect(() => {
    if(currentPlan){
        clearInterval(intervalId)
        dispatch(getActiveSubscription(orgId))
        setDowngradeSuccess(true)
        setDowngrading(false)
    }

    return () => {
        clearInterval(intervalId)
        dispatch(getAppDropdown())
        setDowngrading(false)
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentPlan, dispatch, orgId, setShowPricingModal, setTriggerFreePlan])
  

    const backToPlans = useCallback(() => {
        setTriggerFreePlan(false)
        setShowPricingModal(true)
        dispatch(trackPageViews(null, {
            eventName: 'wa_back_to_plans_clicked',
            track_type: 'event',
        }))
    },[dispatch, setShowPricingModal, setTriggerFreePlan])

    const handleDowngrade = async () => {
        dispatch(trackPageViews(null, {
            eventName: 'wa_downgrade_clicked',
            track_type: 'event',
        }))
        downgradeToFree()
    }

    const closeModal = useCallback(() => {
        setTriggerFreePlan(false)
        setShowPricingModal(false)
    }, [setShowPricingModal, setTriggerFreePlan])
  
    return (
    <Modal 
        wrapClassName='filters-locked-modal select-plan-modal'
        visible={triggerFreePlanPopup}
        closable={false}
        footer={null}
        maskStyle={ { zIndex: '99998', background: 'rgba(22, 30, 53, 0.3)' } }
        getContainer={ () => document.body.querySelector( '.ant-layout-content' )}
        maskClosable={!triggerFreePlanPopup}
    >  
        {
            downgradeSuccess ? 
            <>
                <TitleMessage>Downgrade successful</TitleMessage>
                <Description>You have successfully downgraded your account to the free plan.</Description>
                <ButtonsWrapper>
                    <Button  htmlType="button" type='primary' onClick={closeModal}>
                      Done
                    </Button>
                </ButtonsWrapper>
            </>:
            <>
                <TitleMessage>Are you sure you want to downgrade to the free plan?</TitleMessage>
                <SubTitle>Why the free plan might not be ideal for you:</SubTitle>
                <ListWrapper>
                    {
                        freePlanFeatures.features.map((feature) => 
                            <FeatureList key={feature}>
                                {feature}
                            </FeatureList>
                        )
                    }
                    {
                        freePlanFeatures.disabledFeatures.map((feature) =>
                            <DisabledList key={feature}>
                                {feature}
                            </DisabledList>
                        )
                    }
                </ListWrapper>
                <ButtonsWrapper>
                  <Button htmlType="button" type='link' onClick={backToPlans}>
                      Back to plans
                  </Button>
                  <Button  htmlType="button" type='primary' onClick={handleDowngrade} loading={downgrading}>
                      Downgrade
                  </Button>
                </ButtonsWrapper>
            </>
        }
    </Modal>
  )
}

export default memo(FreePlanModal)