/* eslint-disable no-nested-ternary */
import React, { memo, useCallback, useMemo, useState } from 'react';

import { Modal } from 'antd';
import Cookies from 'universal-cookie';
import styled from 'styled-components';
import ReactLoader from 'components/common/reactLoading';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import { useSelector } from 'react-redux';
import { IReduxState } from 'types/reduxStateTypes';
import Image from 'next/image';
import { Container } from 'components/features/aiSessions/components/styles';
import { Footer } from 'components/shared/GlobalFilter/components/MegaFilterDropdownV2/AiFilter/styles';

const browserCookies = new Cookies();

const TitleMessage = styled.div`
  font-family: 'Roboto';
  font-style: normal;
  font-weight: 500;
  font-size: 18px;
  line-height: 24px;
  color: #161e35;
  text-align: center;
  margin-bottom: 12px;
`;

 const StarterPlanModal = styled(Modal)`
    .ant-modal-content {
      overflow: hidden;
      border-radius: 8px;
    }
    .ant-modal-body {
      padding: 0px !important;
    }
  `;
  
const PlansModalLayoutV2 = ({
  children,
  isLoading: isFetching,
}: {
  children: React.ReactNode;
  isLoading: boolean;
}) => {

  const restrictionContext = useRestrictionContext();
  const {
    showPricingModal,
    setShowPricingModal,
    selfServeFlag,
  } = restrictionContext as any
  const { currentOrgReducer: currentOrg } = useSelector(
    (state: IReduxState) => state
  );

  const loggedInFromAdminDashboard = browserCookies.get(
    'loggedInFromAdminDashboard'
  );

  const { planType, status } = currentOrg;

  const handleCancel = useCallback(() => {
    setShowPricingModal(false);
  }, [setShowPricingModal]);

  const loadingState = useMemo(
    () => isFetching || !selfServeFlag,
    [isFetching, selfServeFlag]
  );

  const maskClosable = useMemo(() => {
    if (loggedInFromAdminDashboard) {
      return true;
    }
    return !(status === 'Expired' && planType === 'trial');
  }, [loggedInFromAdminDashboard, planType, status]);

 
  return (
    <StarterPlanModal
    //   wrapClassName="filters-locked-modal select-plan-modal"
      visible={showPricingModal}
      closable={false}
      footer={null}
      onCancel={handleCancel}
      centered
      width="fit-content"
    //   maskStyle={{ zIndex: '99998', background: 'rgba(22, 30, 53, 0.3)', transformOrigin: 'center' }}
      getContainer={() =>
        document.body.querySelector('.ant-layout-content') || document.body
      }
      maskClosable={maskClosable}
    >
      {loadingState ? (
        <>
          <TitleMessage>Please wait while we fetch your plans.</TitleMessage>
          <ReactLoader />
        </>
      ) : (
        children
      )}
    </StarterPlanModal>
  );
};

export default memo(PlansModalLayoutV2);
