import { Radio } from 'antd'
import React from 'react'

import styled from 'styled-components'


const RadioStyled = styled(Radio)`
    border-radius: ${({recommended}) => recommended ? "0 0 4px 4px" : "4px"};
    border: 1px solid #E8E8E8;
    padding: 16px 18px;
    text-align: center;
    margin-right: unset;
    transition: all 0.4s ease;
    
    &.ant-radio-wrapper-checked{
        background-color: #F7FAFF;
        border-color: #5D97FF;
    }

    &:hover{
        border-color: #5D97FF;
    }

    > .ant-radio{
        display: none;
    }

    span.ant-radio + *{
        all: unset;
        width: 100%;
    }
`

export const H2 = styled.h2`
    font-weight: 500;
    font-size: 18px;
    line-height: 24px;    
    color: #161E35;
    margin-bottom: 4px;
`
export const P = styled.p`
    font-weight: 500;
    font-size: 12px;
    line-height: 24px;    
    color: #454B5D;
`

export const PricingWrapper = styled.div`
    padding: 10px 0;
    margin: 8px 0;
    border-top: 1px solid #E8E8EB;
    border-bottom: 1px solid #E8E8EB;

    > span{
        color: #454B5D;
        font-size: 10px;
        line-height: 24px;
        margin-bottom: 4px;
    }
`

const FeaturesWrapper = styled.ul`
    text-align: left;
    display: flex;
    flex-direction: column;
    gap: 4px;
    max-height: 250px;
    overflow-y: auto;
`

const Feautured = styled.li`
    font-size: 12px;
    line-height: 24px;
    color: #000;
    font-weight: ${({highlighted}) => highlighted && 500};
    position: relative;
    padding-left: 10px;

    &:before{
        content: "";
        position: absolute;
        width: 4px;
        height: 4px;
        border-radius: 50%;
        left: 0;
        top: 10px;
        background: #000;
    }
`

export const H3 = styled.h3`
    font-weight: 700;
    font-size: 22px;
    line-height: 24px;
    color: #161E35;
    margin-bottom: 0;
`

const RecommendedTag = styled.span`
    position: absolute;
    top: -30px;
    left: -1px;
    right: 0;
    width: 101%;
    padding: 2px 10px;
    border-radius: 4px 4px 0 0;
    background-color: #5D97FF;
    color: white;
    font-size: 12px;
    line-height: 24px;
    font-weight: 500;
    border: 1px solid #5D97FF;
`

const SavedTag = styled.div`
    font-size: 12px;
    line-height: 24px;
    font-weight: 400;
    color: ${({isMonthly}) => isMonthly ? "#DC4F44" : "#2DAC7C"};
    background-color: ${({isMonthly}) => isMonthly ? "#FEEEED" : "#EAF9F3"};
    margin: 6px 0;
    border-radius: 20px;
    display: inline-block;
    padding: 0 8px;
`

export const BillingPeriod = styled.div`
    font-size: 12px;
    line-height: 18px;
    margin-top: 6px;
    color: #454B5D;
`


const PlanCard = ({
    id,
    name,
    title,
    subTitle,
    pricingTitle,
    pricingSubtitle,
    savedTag,
    isTailoredPricing,
    features,
    recommended,
    isMonthly
}) => (
    <RadioStyled value={id} recommended={recommended === name}>
        {
            recommended === name &&
            <RecommendedTag>
                Best for your session volume
            </RecommendedTag>
        }
        {
            title && 
            <H2>
                {title}
            </H2>
        }
        {
            subTitle &&
            <P>
                {subTitle}
            </P>
        }
        {
            isTailoredPricing ? 
            <PricingWrapper>
                <span>
                    Tailored pricing
                </span>
                <H3>
                    Let&apos;s talk
                </H3>
            </PricingWrapper>:
            <PricingWrapper>
                {
                pricingTitle && 
                <>
                <H3>
                    {pricingTitle}
                </H3>
                <BillingPeriod>
                    {
                        isMonthly ? "billed monthly" : "billed annually"
                    }
                </BillingPeriod>
                </>
                }
                {
                    savedTag &&
                    <SavedTag isMonthly={isMonthly}>
                        {savedTag}
                    </SavedTag>
                }
                {
                    pricingSubtitle &&
                    <h4>
                        {pricingSubtitle}
                    </h4>
                }
            </PricingWrapper>
        }
        {
            features?.length > 0 && 
            <FeaturesWrapper>
                {
                    features?.map((feature) => {
                        const { enabled } = feature
                        return(
                        enabled &&
                        <Feautured key={feature.name} highlighted={feature.highlighted}>
                            {feature.name}
                        </Feautured>
                        )
                    }
                    )
                }
            </FeaturesWrapper>
        }
    </RadioStyled>
  )

export default PlanCard