/* eslint-disable no-nested-ternary */
import React, { memo, useCallback, useMemo } from 'react'

import { Modal } from 'antd'
import Cookies from 'universal-cookie';
import styled from 'styled-components'
import ReactLoader from 'components/common/reactLoading'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import { useSelector } from 'react-redux'

const browserCookies = new Cookies();

const TitleMessage = styled.div`
	font-family: 'Roboto';
	font-style: normal;
	font-weight: 500;
	font-size: 18px;
	line-height: 24px;
	color: #161E35;
    text-align: center;
    margin-bottom: 12px;
`

const P = styled.p`
    font-weight: 400;
    font-size: 12px;
    line-height: 12px;    
    color: #454B5D;
    text-align: center;
`

const PlansModalLayout = ({children, isLoading:isFetching, planName}) => {

const { showPricingModal, setShowPricingModal, selfServeFlag } = useRestrictionContext() 
const {
    currentOrgReducer: currentOrg
} = useSelector((state) => state)

const loggedInFromAdminDashboard = browserCookies.get(
    'loggedInFromAdminDashboard'
);

const { planType, status } = currentOrg

const handleCancel = useCallback(() => {
    setShowPricingModal(false)
}, [setShowPricingModal])

const loadingState = useMemo(() => isFetching || selfServeFlag === 0 , [isFetching, selfServeFlag]) 

const maskClosable = useMemo(() => {
    if (loggedInFromAdminDashboard) {
        return true;
    }
    return !(status === "Expired" && planType === "trial")
}, [loggedInFromAdminDashboard, planType, status])

return (
    <Modal 
        wrapClassName='filters-locked-modal select-plan-modal'
        visible={showPricingModal}
        closable={false}
        footer={null}
        onCancel={ handleCancel }
        maskStyle={ { zIndex: '99998', background: 'rgba(22, 30, 53, 0.3)' } }
        getContainer={ () => document.body.querySelector( '.ant-layout-content' )}
        maskClosable={maskClosable}
    >  
    { 
        loadingState ? 
            <>
            <TitleMessage>
              Please wait while we fetch your plans.
            </TitleMessage>
             <ReactLoader />
            </>
            :    
            <>
            <TitleMessage>
                {
                    planName || 'Please choose a plan:'
                }
            </TitleMessage>
            <P>Essentials for teams to understand the user journey and stay on top of key metrics</P>
            {children}
            </>         
    }
    </Modal>
  )
}

export default memo(PlansModalLayout)