import React, { memo, useCallback } from 'react'

import { trackPageViews } from 'redux/actions/trackingReport';
import { useDispatch, useSelector } from 'react-redux';

import { Button, Form, Radio } from 'antd'

import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';

import { planOptions } from 'Utils/constants';
import PlansModalLayout from '../PlansModalLayout'
import PlanCard from '../PlanCard';

import { CardsContainer, ButtonsWrapper, FormStyled, FormItemStyled } from './styles';

const NonSelfServePlansPopup = ({setTriggerFreePlanPopup}) => {
  const [form] = Form.useForm();

  const {
    currentOrgReducer: currentOrg
  } = useSelector(state => state)

  const { setTriggerRequestQuote, setShowPricingModal } = useRestrictionContext();

  const dispatch = useDispatch()

  const { planType } = currentOrg

  const planSelected = Form.useWatch('plan', form)

  const onFinish = useCallback(() => {
    setTriggerRequestQuote(true)
    dispatch( trackPageViews( null, {
			eventName: 'wa_continue_with_plan_clicked',
			track_type: 'event',
		} ) )
  }, [dispatch, setTriggerRequestQuote])

  const triggerFreePlanPopup = useCallback(() => {
    setShowPricingModal(false)
    setTriggerFreePlanPopup(true)
    dispatch( trackPageViews( null, {
      eventName: 'wa_downgrade_to_free_plan_clicked',
      track_type: 'event',
    } ) )
  }, [dispatch, setShowPricingModal, setTriggerFreePlanPopup])

return (
    <PlansModalLayout>
      <FormStyled
        form={form}
        onFinish={onFinish}
        initialValues = {{plan: 'growth'}}
      >
        <FormItemStyled
          name="plan"
          rules={[
            {
              required: true,
              message: 'Please select atleast one option.',
            },
          ]}
        >
          <Radio.Group >
            <CardsContainer>
              {
                planOptions.map((option) => (
                  <PlanCard 
                    key={option.name}
                    id={option.name}
                    name={option.name}
                    title={option.title}
                    subTitle={option.subTitle}
                    features={option.features}
                    isTailoredPricing
                  />
                ))
              }
            </CardsContainer>
          </Radio.Group>
        </FormItemStyled>
        <FormItemStyled>
          <ButtonsWrapper>
            {
             planType === "trial" &&
              <Button key="button" type='link' onClick={triggerFreePlanPopup}>
                  Downgrade to free plan
              </Button>
            }
          <Button  htmlType="submit" type='primary'>
              Continue with {planSelected} plan
          </Button>
          </ButtonsWrapper>
        </FormItemStyled>
      </FormStyled>
    </PlansModalLayout>
  )
}

export default memo(NonSelfServePlansPopup)