import React, { memo, useCallback, useState, useEffect, useMemo } from 'react'
import { useSelector } from 'react-redux'

import AppApi from 'services/appApi'
import { rollbar } from 'components/common/rollbar'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'

import NewRequestQuoteForm from './NewRequestQuoteForm'
import SelfServePlanPopup from './SelfServePlanPopup'
import NonSelfServePlansPopup from './NonSelfServePlansPopup'
import FreePlanModal from './FreePlanModal'

const PlanBasedPricingPopup = () => {
    const {
        currentOrgReducer: currentOrg,
        urlReducer: urlQuery
    } = useSelector((state) => state)

    const { parentType } = urlQuery
    const { planType, status, orgId } = currentOrg

    const [planData, setPlanData] = useState()
    const [isLoading, setIsLoading] = useState(true)
    const [triggerFreePlanPopup, setTriggerFreePlanPopup] = useState(false)

    const { selfServeFlag, triggerRequestQuote, showPricingModal, setShowPricingModal} = useRestrictionContext()

    useEffect(() => {
      if(status !== "Expired"){
        setShowPricingModal(false)
      }
    }, [ setShowPricingModal, status, parentType])

    useEffect(() => {
      if(status === "Expired" && planType === "trial"){
        setShowPricingModal(true)
      }
    }, [planType, setShowPricingModal, status])

    const nonSelfServeFormConditions = useMemo(() => !selfServeFlag && ((planType === "trial" && status !== "Expired") || planType === "free"), [planType, selfServeFlag, status])

    const selfServeConditions = useMemo(() => selfServeFlag && (planType === "free" ||  planType === "trial"), [planType, selfServeFlag])

    const getPlans = useCallback(async (organizationId) => {
      try{
        const res = await AppApi.getNewSelfServePlans(organizationId);
        if(res.status === 200){
          setPlanData(res.data.data)
          setIsLoading(false)
        }
      }catch{
        (err) => rollbar.error(err)
      }
    }, [])

    useEffect(() => {
      if(selfServeConditions){
        getPlans(orgId)
      }
    }, [orgId, getPlans, selfServeConditions])

    if(selfServeFlag === 0){
      return null;
    }

    if(triggerFreePlanPopup){
      return <FreePlanModal setTriggerFreePlan={setTriggerFreePlanPopup} triggerFreePlanPopup={triggerFreePlanPopup}/>
    }

    if(triggerRequestQuote || nonSelfServeFormConditions){
      return <NewRequestQuoteForm showPricingModal={showPricingModal} setShowPricingModal={setShowPricingModal}/>
    }

    if(selfServeConditions){
      return <SelfServePlanPopup planData={planData} isLoading={isLoading} triggerFreePlanPopup={triggerFreePlanPopup} setTriggerFreePlanPopup={setTriggerFreePlanPopup}/>
    }

    if(!selfServeFlag && (status === "Expired" && planType === "trial")){
      return <NonSelfServePlansPopup triggerFreePlanPopup={triggerFreePlanPopup} setTriggerFreePlanPopup={setTriggerFreePlanPopup}/>
    }

  return (
    <NewRequestQuoteForm showPricingModal={showPricingModal} setShowPricingModal={setShowPricingModal}/>
  )
}

export default memo(PlanBasedPricingPopup)